import{c as d}from"./chunks/caution.DjUmlKPe.js";import{$ as l,Q as o,j as p,m as s,h as c,ay as t,n as a,o as r,S as u,g as i}from"./chunks/framework.Cr5Oofs_.js";import"./chunks/alert.CQjRNMKX.js";/* empty css                                                                                  */const m="/pyclickmouse/imgs/en/mergeSteps.png",x=JSON.parse('{"title":"Participating in Collaboration","description":"Introduction to how to participate in collaboration","frontmatter":{"title":"Participating in Collaboration","description":"Introduction to how to participate in collaboration","layout":"doc"},"headers":[],"relativePath":"en/develop/contributing/github.md","filePath":"en/develop/contributing/github.md"}'),h={name:"en/develop/contributing/github.md"},k=Object.assign(h,{setup(b){return(f,e)=>{const n=l("Mermaid");return o(),p("div",null,[e[2]||(e[2]=s(`<h1 id="participating-in-collaboration" tabindex="-1">Participating in Collaboration <a class="header-anchor" href="#participating-in-collaboration" aria-label="Permalink to &quot;Participating in Collaboration&quot;">​</a></h1><h2 id="commit-message" tabindex="-1">commit message <a class="header-anchor" href="#commit-message" aria-label="Permalink to &quot;commit message&quot;">​</a></h2><p>Need follow following format:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Update type(Update module):(optional)(version number) (Update summary):</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- [(optional)Sub update type]Update content 1</span></span>
<span class="line"><span>- [(optional)Sub update type]Update content 2</span></span>
<span class="line"><span>- ...</span></span></code></pre></div><p>Update types have these contents:</p><table tabindex="0"><thead><tr><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>✅feat</td><td>New feature</td></tr><tr><td>🔧modify</td><td>Modify feature</td></tr><tr><td>🐛fix</td><td>Fix bug</td></tr><tr><td>⚒️refactor</td><td>Refactor</td></tr><tr><td>📃docs</td><td>Modify documentation, e.g. README</td></tr><tr><td>❇️style</td><td>Modify code style, not affecting functionality</td></tr><tr><td>🔎test</td><td>Add test, modify test</td></tr><tr><td>📆chore</td><td>Miscellaneous, e.g. modify .gitignore</td></tr><tr><td>⏫perf</td><td>Performance optimization</td></tr><tr><td>🛒ci</td><td>CI/CD related changes</td></tr><tr><td>🚅build</td><td>Modify build system or dependencies</td></tr><tr><td>◀️revert</td><td>Rollback</td></tr><tr><td>🔡dependency</td><td>Dependency update</td></tr><tr><td>❌remove</td><td>Remove deprecated components</td></tr><tr><td>↪️move</td><td>Moved components</td></tr><tr><td>❓unknown</td><td>Unknown type</td></tr><tr><td>Custom</td><td>Try to describe with intuitive English word, best with emoji</td></tr></tbody></table><p>When content many need add update type prompt for update content</p><h2 id="branches" tabindex="-1">Branches <a class="header-anchor" href="#branches" aria-label="Permalink to &quot;Branches&quot;">​</a></h2><p>Please update according to branch structure shown in this diagram: <img src="`+m+'" alt="Merge Steps"></p><p>Created branches need start with <code>feature/</code> to indicate feature branch, or create a fork, and develop in fork branch.</p><p>When publishing pr need select <strong>merge to <code>develop</code> branch</strong>.</p><h2 id="version-number" tabindex="-1">Version Number <a class="header-anchor" href="#version-number" aria-label="Permalink to &quot;Version Number&quot;">​</a></h2><p>clickmouse version format: <code>A.B.C.D[(alpha | beta |.dev | rc) E]</code></p><h2 id="official-version" tabindex="-1">Official Version <a class="header-anchor" href="#official-version" aria-label="Permalink to &quot;Official Version&quot;">​</a></h2><p>Official version without .dev, alpha, beta or rc suffix.</p><p>A position represents major update, has code level changes. E.g. 1.0 upgrade to 2.0 refactored code.</p><p>B position represents normal update, usually updates some major features.</p><p>C position represents fix update, usually updates some minor features and some bugs.</p><p>D position represents version code, usually +1 when A, B, C positions change. Also possible A, B, C positions not change, D position +1, this represents emergency update, usually fixes several major impact bugs.</p><h2 id="test-version" tabindex="-1">Test Version <a class="header-anchor" href="#test-version" aria-label="Permalink to &quot;Test Version&quot;">​</a></h2><p>Test version with .dev, alpha, beta or rc suffix.</p><p>Usually preceding <code>A.B.C.D</code> unchanged during test cycle, represents next version.</p><p><code>.dev</code> represents early development update, functionality unstable, many bugs, located at version project initial stage.The new features in this phase will be put in the lab and turned off by default.</p><p><code>alpha</code> represents late development update, functionality incomplete, many bugs, located at version project early stage.The new features in this phase will be put in the lab and turned off by default.</p><p><code>beta</code> represents release test update, functionality complete, fewer bugs, will not add new features, located at version project middle stage. It is usually released in the middle of the development cycle and will gradually merge features from the lab.</p><p><code>rc</code> represents pre-release version, functionality complete, fewer bugs, will fix some important security issues or bugs, closest to official version, about to release official version, located at version project final stage.</p><h2 id="issue" tabindex="-1">issue <a class="header-anchor" href="#issue" aria-label="Permalink to &quot;issue&quot;">​</a></h2><ul><li>Title format: <code>[Type] Title</code> etc., can write casually, but need accurately describe update content.</li><li>Content should accurately write your requirements, and optionally give solutions, upload screenshots, add additional information (e.g. clickmouse version number)</li><li>Types are <code>bug</code>, <code>enhancement</code>, <code>question</code> etc.</li><li>We provided some templates, can directly use.</li><li>Use <code>labels</code> to mark issue type, e.g. <code>bug</code>, <code>enhancement</code>, <code>question</code> etc.</li><li>Set issue <code>milestone</code> to version you want to apply.</li><li>Security issues please see <a href="./SECURITY.html">Security Documentation</a>.</li></ul><h2 id="pr" tabindex="-1">pr <a class="header-anchor" href="#pr" aria-label="Permalink to &quot;pr&quot;">​</a></h2><ul><li>Title format: <code>[Type] Title</code></li><li>Use <code>labels</code> to mark pr type, e.g. <code>bug</code>, <code>enhancement</code>, <code>question</code> etc.</li><li>Associate issue, so we can know which issue this pr solves.</li><li>Need accurately write update content, associate to version number milestone.</li><li>Optionally add implementation ideas</li></ul><h3 id="specifications" tabindex="-1">Specifications <a class="header-anchor" href="#specifications" aria-label="Permalink to &quot;Specifications&quot;">​</a></h3><p>Our pr merge order:</p>',32)),(o(),c(u,null,{default:t(()=>[r(n,{id:"mermaid-300",class:"mermaid",graph:"graph%20LR%0AA(Other%20user%20feature%20development%20branch)%20--%3E%20B(develop%20branch)%0AB%20--%3E%20C(main%20branch)%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=i("p",null,"pr no specific format, but must clearly describe update content, associate to version number milestone; title need briefly describe update content, if fixed or added suggestions in issue, write that issue number in this line, if multiple duplicate issues appear, only write one, and simply describe this bug.",-1)),e[4]||(e[4]=i("h3",{id:"express-pr",tabindex:"-1"},[a("Express pr "),i("a",{class:"header-anchor",href:"#express-pr","aria-label":'Permalink to "Express pr"'},"​")],-1)),r(d,{title:"Caution"},{default:t(()=>[...e[1]||(e[1]=[a(" Express pr please use carefully ",-1)])]),_:1}),e[5]||(e[5]=s('<ul><li>Express pr means skip some normal pr merge branch steps, to faster merge to target branch functionality.</li><li>Title format: <code>[✈️Express] Title</code></li><li>Using express must explain reason in pr description</li></ul><p>If someone express merge, but didn&#39;t write express merge reason, then reject merge that person&#39;s branch.</p><p>Express pr has high priority, will process first.</p><h2 id="milestone" tabindex="-1">milestone <a class="header-anchor" href="#milestone" aria-label="Permalink to &quot;milestone&quot;">​</a></h2><ul><li>We set a milestone for each version, to manage that version&#39;s issues and pr.</li><li>Need each issue or pr associate to a milestone, so we can know if that issue or pr added in next version.</li><li>milestone format:<code>dev_version number</code></li></ul>',5))])}}});export{x as __pageData,k as default};
